ALTER POLICY "sparra_revision_read" ON "sparra_knowledge_revision" TO runtime USING ("sparra_knowledge_revision"."workspace_id"::text = current_setting('app.tenant_id',true) and current_setting('app.tenant_id',true) <> '00000000-0000-0000-0000-000000000000' and exists (select 1 from public.workspace where workspace.id = "sparra_knowledge_revision"."workspace_id" and workspace.lifecycle = 'active'));--> statement-breakpoint
ALTER POLICY "sparra_revision_insert" ON "sparra_knowledge_revision" TO runtime WITH CHECK ("sparra_knowledge_revision"."workspace_id"::text = current_setting('app.tenant_id',true) and current_setting('app.tenant_id',true) <> '00000000-0000-0000-0000-000000000000' and exists (select 1 from public.workspace where workspace.id = "sparra_knowledge_revision"."workspace_id" and workspace.lifecycle = 'active'));